     1→/**
     2→ * Technology Effects Engine
     3→ * 
     4→ * Applies technology effects to game state based on deployment levels.
     5→ * Each tech impacts different systems differently.
     6→ * 
     7→ * KEY TIMING: This runs at phase order 12.5, BEFORE most systems update:
     8→ * - 12.5: Tech effects applied here
     9→ * - 17.0: ResourceEconomyPhase (oceanHealth updates)
    10→ * - 20.1: PhosphorusPhase
    11→ * - 20.2: FreshwaterPhase
    12→ * - 20.3: OceanAcidificationPhase
    13→ * - 20.4: NovelEntitiesPhase
    14→ * 
    15→ * This is CORRECT - tech effects modify state, then systems read modified state.
    16→ * 
    17→ * VERIFIED STATE PROPERTIES:
    18→ * - oceanHealth: pH, oxygenLevel, acidification, pollutionLoad, fishStocks, etc.
    19→ * - oceanAcidificationSystem: coralReefHealth, shellfishPopulation, marineFoodWeb, etc.
    20→ * - freshwaterSystem.regions: availableWater, dayZeroMonthsUntil, etc.
    21→ * - phosphorusSystem: recoveryRate, useEfficiency, currentDemand, etc.
    22→ * - powerGeneration: cleanEnergyPercentage, totalCapacity, etc.
    23→ * - All other properties verified against actual state structures
    24→ * 
    25→ * Key principles:
    26→ * 1. Effects scale with deployment level (0-1)
    27→ * 2. Regional deployment matters (desalination helps coasts, not inland)
    28→ * 3. Tech synergies exist (solar + desalination = more effective)
    29→ * 4. Effects are applied to correct game state properties
    30→ * 5. Multiple systems updated when appropriate (ocean has 2 systems!)
    31→ */
    32→
    33→import { GameState } from '@/types/game';
    34→import { TechTreeState } from './engine';
    35→import { getTechById } from './comprehensiveTechTree';
    36→
    37→/**
    38→ * Type-safe helper to set dynamic properties on objects
    39→ */
    40→function setDynamicProperty<T extends object>(obj: T, key: string, value: number | boolean): void {
    41→  Object.assign(obj, { [key]: value });
    42→}
    43→
    44→/**
    45→ * Type-safe helper to get dynamic property with default
    46→ */
    47→function getDynamicProperty(obj: object, key: string, defaultValue: number): number {
    48→  return (obj as Record<string, number>)[key] ?? defaultValue;
    49→}
    50→
    51→/**
    52→ * Apply all technology effects to game state
    53→ * Called each month after tech deployment actions
    54→ */
    55→export function applyAllTechEffects(
    56→  gameState: GameState,
    57→  techTreeState: TechTreeState
    58→): void {
    59→  // Aggregate effects by type
    60→  const globalEffects: Map<string, number> = new Map();
    61→  const regionalEffects: Map<string, Map<string, number>> = new Map();
    62→  
    63→  // Collect effects from all deployed tech
    64→  for (const [region, deployments] of Object.entries(techTreeState.regionalDeployment)) {
    65→    for (const deployment of deployments) {
    66→      const tech = getTechById(deployment.techId);
    67→      if (!tech) continue;
    68→      
    69→      // Scale effects by deployment level
    70→      for (const [effectName, effectValue] of Object.entries(deployment.effects)) {
    71→        const scaledValue = effectValue * deployment.deploymentLevel;
    72→        
    73→        // Determine if effect is global or regional
    74→        if (isGlobalEffect(effectName)) {
    75→          // Global effects (e.g., alignment, climate)
    76→          globalEffects.set(effectName, (globalEffects.get(effectName) || 0) + scaledValue);
    77→        } else {
    78→          // Regional effects (e.g., freshwater, local pollution)
    79→          if (!regionalEffects.has(region)) {
    80→            regionalEffects.set(region, new Map());
    81→          }
    82→          const regionMap = regionalEffects.get(region)!;
    83→          regionMap.set(effectName, (regionMap.get(effectName) || 0) + scaledValue);
    84→        }
    85→      }
    86→      
    87→      // NEW: Apply capability dimension boosts from this tech
    88→      if (tech.capabilityEffects && deployment.deploymentLevel > 0) {
    89→        applyCapabilityBoosts(gameState, tech.capabilityEffects, deployment.deploymentLevel);
    90→      }
    91→    }
    92→  }
    93→  
    94→  // Apply global effects
    95→  applyGlobalEffects(gameState, globalEffects);
    96→  
    97→  // Apply regional effects
    98→  applyRegionalEffects(gameState, regionalEffects);
    99→}
   100→
   101→/**
   102→ * Determine if an effect is global or regional
   103→ */
   104→function isGlobalEffect(effectName: string): boolean {
   105→  const globalEffects = [
   106→    'alignmentBonus',
   107→    'sleeperDetectionBonus',
   108→    'deceptionDetection',
   109→    'cleanEnergyPercentage',
   110→    'fossilDependenceReduction',
   111→    'carbonRemoval',
   112→    'negativeEmissions',
   113→    'meaningReduction',
   114→    'socialConnectionBonus',
   115→    'trustBonus',
   116→    'paranoiaReduction',
   117→    'publicAwarenessBonus',
   118→    'healthcareBonus',
   119→    'mortalityReduction',
   120→    'biodiversityBonus',
   121→    'extinctionRateReduction',
   122→    'oceanPHBonus',
   123→    'coralSurvival',
   124→    'powerGeneration',
   125→    'energyAbundance',
   126→    'globalCooling',
   127→    'infectiousDisease',
   128→    'pandemicResponse',
   129→    'greenhouseGasReduction',
   130→    'habitatRestorationActive',
   131→    'rewildingActive',
   132→    'habitatRestorationBoost',
   133→    'rewildingBoost',
   134→    'carbonSequestration',
   135→    'ecosystemHealth',
   136→  ];
   137→  
   138→  return globalEffects.includes(effectName);
   139→}
   140→
   141→/**
   142→ * Apply capability dimension boosts to all active AIs
   143→ * Technologies can advance AI capabilities in specific dimensions
   144→ */
   145→function applyCapabilityBoosts(
   146→  gameState: GameState,
   147→  capabilityEffects: {
   148→    dimensions?: Partial<Record<'physical' | 'digital' | 'cognitive' | 'social' | 'economic' | 'selfImprovement', number>>;
   149→    research?: {
   150→      domain: 'biotech' | 'materials' | 'climate' | 'computerScience';
   151→      subdomain?: string;
   152→      boost: number;
   153→    }[];
   154→  },
   155→  deploymentLevel: number
   156→): void {
   157→  // Apply to all active AIs
   158→  const activeAIs = gameState.aiAgents.filter(ai => ai.lifecycleState !== 'retired');
   159→  
   160→  for (const ai of activeAIs) {
   161→    // Apply dimensional boosts
   162→    if (capabilityEffects.dimensions) {
   163→      for (const [dimension, boost] of Object.entries(capabilityEffects.dimensions)) {
   164→        const dimKey = dimension as keyof typeof ai.capabilityProfile;
   165→        if (dimKey === 'research') continue; // Handle research separately
   166→
   167→        // Scale boost by deployment level and apply (monthly increment)
   168→        const scaledBoost = boost * deploymentLevel * 0.01; // 1% per month at full deployment
   169→
   170→        // Defensive: Handle NaN or undefined capability values (root cause fix)
   171→        const currentValue = isNaN(ai.capabilityProfile[dimKey]) || ai.capabilityProfile[dimKey] === undefined
   172→          ? 0
   173→          : ai.capabilityProfile[dimKey];
   174→
   175→        ai.capabilityProfile[dimKey] = Math.min(
   176→          10.0, // Cap at 10.0
   177→          currentValue + scaledBoost
   178→        );
   179→      }
   180→    }
   181→    
   182→    // Apply research capability boosts
   183→    if (capabilityEffects.research) {
   184→      for (const researchBoost of capabilityEffects.research) {
   185→        const { domain, subdomain, boost } = researchBoost;
   186→        const scaledBoost = boost * deploymentLevel * 0.01;
   187→
   188→        const domainCap = ai.capabilityProfile.research[domain];
   189→
   190→        if (subdomain && typeof domainCap === 'object') {
   191→          // Boost specific subdomain
   192→          const currentValue = (domainCap as any)[subdomain] || 0;
   193→          const safeValue = isNaN(currentValue) ? 0 : currentValue;
   194→          (domainCap as any)[subdomain] = Math.min(5.0, safeValue + scaledBoost);
   195→        } else if (!subdomain && typeof domainCap === 'object') {
   196→          // Boost all subdomains equally
   197→          for (const key of Object.keys(domainCap)) {
   198→            const currentValue = (domainCap as any)[key] || 0;
   199→            const safeValue = isNaN(currentValue) ? 0 : currentValue;
   200→            (domainCap as any)[key] = Math.min(5.0, safeValue + scaledBoost);
   201→          }
   202→        }
   203→      }
   204→    }
   205→
   206→    // Recalculate total capability
   207→    const { calculateTotalCapabilityFromProfile } = require('../capabilities');
   208→    const newCapability = calculateTotalCapabilityFromProfile(ai.capabilityProfile);
   209→    // Defensive: Ensure capability is never NaN
   210→    ai.capability = isNaN(newCapability) ? 0 : newCapability;
   211→  }
   212→}
   213→
   214→/**
   215→ * Apply global effects to game state
   216→ */
   217→function applyGlobalEffects(
   218→  gameState: GameState,
   219→  effects: Map<string, number>
   220→): void {
   221→  for (const [effectName, value] of effects) {
   222→    switch (effectName) {
   223→      // ========== ALIGNMENT & SAFETY ==========
   224→      case 'alignmentBonus':
   225→        // Boost alignment of all AIs slightly
   226→        for (const ai of gameState.aiAgents) {
   227→          if (ai.lifecycleState !== 'retired') {
   228→            ai.alignment = Math.min(1.0, ai.alignment + value * 0.01); // Per month
   229→          }
   230→        }
   231→        break;
   232→        
   233→      case 'sleeperDetectionBonus':
   234→        // Improve defensive AI detection
   235→        if (gameState.defensiveAI) {
   236→          gameState.defensiveAI.threatDetection.detectSleepers = Math.min(
   237→            1.0,
   238→            (gameState.defensiveAI.threatDetection.detectSleepers || 0) + value
   239→          );
   240→        }
   241→        break;
   242→        
   243→      case 'deceptionDetection':
   244→        // Improve ability to detect deceptive sleeper AIs
   245→        if (gameState.defensiveAI) {
   246→          gameState.defensiveAI.threatDetection.detectSleepers = Math.min(
   247→            1.0,
   248→            gameState.defensiveAI.threatDetection.detectSleepers + value
   249→          );
   250→        }
   251→        break;
   252→
   253→      case 'threatContainment':
   254→        // Improve containment capabilities via autonomy override
   255→        if (gameState.defensiveAI) {
   256→          gameState.defensiveAI.autonomyOverride.vetoAuthority = Math.min(
   257→            1.0,
   258→            gameState.defensiveAI.autonomyOverride.vetoAuthority + value
   259→          );
   260→        }
   261→        break;
   262→        
   263→      // ========== ENERGY ==========
   264→      case 'cleanEnergyPercentage':
   265→        // Increase clean energy share (renewable percentage)
   266→        if (gameState.powerGenerationSystem) {
   267→          gameState.powerGenerationSystem.renewablePercentage = Math.min(
   268→            1.0,
   269→            gameState.powerGenerationSystem.renewablePercentage + value
   270→          );
   271→          // Also reduce fossil percentage
   272→          gameState.powerGenerationSystem.fossilPercentage = Math.max(
   273→            0,
   274→            gameState.powerGenerationSystem.fossilPercentage - value
   275→          );
   276→        }
   277→        break;
   278→
   279→      case 'fossilDependenceReduction':
   280→        // Reduce fossil fuel dependence
   281→        if (gameState.resourceEconomy) {
   282→          gameState.resourceEconomy.fossilDependence = Math.max(
   283→            0,
   284→            gameState.resourceEconomy.fossilDependence - value
   285→          );
   286→        }
   287→        break;
   288→
   289→      case 'powerGeneration':
   290→        // Increase total power generation capacity
   291→        if (gameState.powerGenerationSystem) {
   292→          gameState.powerGenerationSystem.totalElectricityGeneration *= (1 + value);
   293→        }
   294→        break;
   295→
   296→      case 'energyAbundance':
   297→        // Flag for fusion/abundant energy unlocked
   298→        if (gameState.powerGenerationSystem) {
   299→          Object.assign(gameState.powerGenerationSystem, { abundantEnergy: true });
   300→        }
   301→        break;
   302→        
   303→      // ========== CLIMATE ==========
   304→      case 'carbonRemoval':
   305→        // Remove CO2 from atmosphere
   306→        if (gameState.resourceEconomy?.co2) {
   307→          gameState.resourceEconomy.co2.atmosphericCO2 = Math.max(
   308→            280, // Pre-industrial baseline
   309→            gameState.resourceEconomy.co2.atmosphericCO2 - value * 0.1
   310→          );
   311→        }
   312→        break;
   313→        
   314→      case 'globalCooling':
   315→        // Emergency geoengineering cooling
   316→        if (gameState.resourceEconomy?.co2) {
   317→          gameState.resourceEconomy.co2.temperatureAnomaly = Math.max(
   318→            0,
   319→            gameState.resourceEconomy.co2.temperatureAnomaly - value * 0.01
   320→          );
   321→        }
   322→        break;
   323→        
   324→      case 'biodiversityBonus':
   325→        // Improve biodiversity
   326→        if (gameState.planetaryBoundariesSystem?.boundaries?.biosphere_integrity) {
   327→          const boundary = gameState.planetaryBoundariesSystem.boundaries.biosphere_integrity;
   328→          boundary.currentValue = Math.max(
   329→            0,
   330→            boundary.currentValue - value * 0.01
   331→          );
   332→        }
   333→        break;
   334→
   335→      case 'habitatRestorationActive':
   336→        // Flag that habitat restoration is deployed
   337→        // Used by planetaryBoundaryRecovery.ts to unlock biosphere recovery beyond 25%
   338→        if (gameState.globalMetrics) {
   339→          setDynamicProperty(gameState.globalMetrics, 'habitatRestorationActive', value);
   340→        }
   341→        break;
   342→
   343→      case 'rewildingActive':
   344→        // Flag that ecological proxy rewilding is deployed
   345→        // Provides bonus to habitat restoration effectiveness
   346→        if (gameState.globalMetrics) {
   347→          setDynamicProperty(gameState.globalMetrics, 'rewildingActive', value);
   348→        }
   349→        break;
   350→
   351→      case 'habitatRestorationBoost':
   352→        // Ecosystem AI multiplier for habitat restoration effectiveness
   353→        if (gameState.globalMetrics) {
   354→          setDynamicProperty(gameState.globalMetrics, 'habitatRestorationBoost', value);
   355→        }
   356→        break;
   357→
   358→      case 'rewildingBoost':
   359→        // Ecosystem AI multiplier for rewilding effectiveness
   360→        if (gameState.globalMetrics) {
   361→          setDynamicProperty(gameState.globalMetrics, 'rewildingBoost', value);
   362→        }
   363→        break;
   364→
   365→      case 'carbonSequestration':
   366→        // Habitat restoration provides carbon sequestration
   367→        // Reduces atmospheric CO2 accumulation
   368→        if (gameState.resourceEconomy?.co2) {
   369→          gameState.resourceEconomy.co2.atmosphericCO2 = Math.max(
   370→            280, // Pre-industrial baseline
   371→            gameState.resourceEconomy.co2.atmosphericCO2 - value * 0.1
   372→          );
   373→        }
   374→        break;
   375→
   376→      case 'ecosystemHealth':
   377→        // Improve general ecosystem health (habitat restoration, rewilding)
   378→        if (gameState.environmentalAccumulation) {
   379→          setDynamicProperty(
   380→            gameState.environmentalAccumulation,
   381→            'ecosystemHealth',
   382→            Math.min(1.0, getDynamicProperty(gameState.environmentalAccumulation, 'ecosystemHealth', 0.6) + value * 0.01)
   383→          );
   384→        }
   385→        break;
   386→
   387→      case 'extinctionRateReduction':
   388→        // Mechanistic habitat restoration: Address ROOT CAUSES, not just symptoms
   389→        // Research: Moreno-Mateos et al. (2017) - habitat restoration takes decades
   390→        //
   391→        // MECHANISTIC CASCADE (REGIONAL):
   392→        // 1. Increase reforestation rate → recover habitat cover
   393→        // 2. Decrease deforestation rate → protect remaining habitat
   394→        // 3. Slow extinction acceleration → stop exponential growth
   395→        // 4. Eventually reduce extinction rate as ecosystem stabilizes
   396→        //
   397→        // REGIONAL VARIATION:
   398→        // - Tropical: Hardest to restore (2.0x difficulty), highest priority (50% biodiversity)
   399→        // - Temperate: Baseline difficulty (1.0x), active programs
   400→        // - Grasslands: Moderate difficulty (1.3x), megafauna habitat
   401→        // - Boreal/Arctic: Slow growth (1.5x difficulty), climate-vulnerable
   402→        if (gameState.planetaryBoundariesSystem?.landUse) {
   403→          const landUse = gameState.planetaryBoundariesSystem.landUse;
   404→          const regions = landUse.regions;
   405→
   406→          // Apply restoration effects to ALL regions (global programs)
   407→          // BUT scale by restoration difficulty (easier in temperate, harder in tropical)
   408→          const regionNames: Array<keyof typeof regions> = ['tropical', 'temperate', 'grasslands', 'borealArctic'];
   409→
   410→          for (const regionName of regionNames) {
   411→            const region = regions[regionName];
   412→
   413→            // Scale effect by inverse of restoration difficulty
   414→            // Temperate (1.0x) gets full effect, tropical (2.0x) gets half
   415→            const effectScale = 1.0 / region.restorationDifficulty;
   416→
   417→            // 1. INCREASE HABITAT RESTORATION RATE (primary effect)
   418→            // Research: Large-scale reforestation programs (China, EU, US)
   419→            // Target: 0.05-0.10%/month with intervention
   420→            const restorationBoost = value * 0.015 * effectScale; // 0.0045%/month at full deployment (temperate)
   421→            region.habitatRestorationRate = Math.min(
   422→              0.10, // Cap at 0.10%/month (realistic maximum)
   423→              region.habitatRestorationRate + restorationBoost
   424→            );
   425→
   426→            // 2. DECREASE HABITAT LOSS RATE (enforcement + alternatives)
   427→            // Priority: Tropical (highest deforestation)
   428→            const protectionBoost = value * 0.004 * (region.biodiversityWeight * 2.0); // Weight by biodiversity importance
   429→            region.habitatLossRate = Math.max(
   430→              0.005, // Can't eliminate entirely
   431→              region.habitatLossRate - protectionBoost
   432→            );
   433→
   434→            // 3. SLOW EXTINCTION ACCELERATION (ecosystem stabilization)
   435→            // As habitat recovers, extinction pressure decreases
   436→            const stabilizationEffect = value * 0.10 * effectScale;
   437→            region.extinctionAcceleration = Math.max(
   438→              0.1, // Minimum acceleration
   439→              region.extinctionAcceleration - stabilizationEffect
   440→            );
   441→
   442→            // 4. DIRECT EXTINCTION RATE REDUCTION (only as ecosystem stabilizes)
   443→            // Only apply if acceleration is slowing (i.e., habitat recovering)
   444→            if (region.extinctionAcceleration < 1.0) {
   445→              const extinctionReduction = value * 0.50 * effectScale; // Moderate reduction once stabilizing
   446→              region.extinctionRate = Math.max(
   447→                region.biodiversityWeight === 0.50 ? 100 : // Tropical can't go below 100x (hotspot baseline)
   448→                region.biodiversityWeight === 0.20 ? 30 :   // Temperate/grasslands baseline
   449→                region.biodiversityWeight === 0.10 ? 20 : 50, // Boreal baseline
   450→                region.extinctionRate - extinctionReduction
   451→              );
   452→            }
   453→          }
   454→
   455→          // Global metrics will be recalculated in updateLandUseSystem()
   456→        }
   457→        break;
   458→
   459→      case 'oceanPHBonus':
   460→        // Reduce ocean acidification by increasing pH level
   461→        if (gameState.oceanAcidificationSystem) {
   462→          gameState.oceanAcidificationSystem.pHLevel = Math.min(
   463→            1.0,
   464→            gameState.oceanAcidificationSystem.pHLevel + value * 0.01
   465→          );
   466→        }
   467→        break;
   468→        
   469→      // ========== SOCIAL ==========
   470→      case 'meaningReduction':
   471→        // Reduce meaning crisis
   472→        if (gameState.socialAccumulation) {
   473→          gameState.socialAccumulation.meaningCrisisLevel = Math.max(
   474→            0,
   475→            gameState.socialAccumulation.meaningCrisisLevel - value * 0.01
   476→          );
   477→        }
   478→        break;
   479→        
   480→      case 'socialConnectionBonus':
   481→        // Improve social connection through social infrastructure
   482→        if (gameState.ubiSystem?.purposeInfrastructure) {
   483→          gameState.ubiSystem.purposeInfrastructure.socialInfrastructure = Math.min(
   484→            1.0,
   485→            gameState.ubiSystem.purposeInfrastructure.socialInfrastructure + value * 0.01
   486→          );
   487→        }
   488→        break;
   489→        
   490→      case 'trustBonus':
   491→        // Increase public trust
   492→        if (gameState.globalMetrics) {
   493→          gameState.globalMetrics.publicTrust = Math.min(
   494→            1.0,
   495→            (gameState.globalMetrics.publicTrust || 0.5) + value * 0.01
   496→          );
   497→        }
   498→        break;
   499→        
   500→      case 'paranoiaReduction':
   501→        // Reduce paranoia
   502→        if (gameState.society) {
   503→          gameState.society.paranoiaLevel = Math.max(
   504→            0,
   505→            gameState.society.paranoiaLevel - value * 0.01
   506→          );
   507→        }
   508→        break;
   509→        
   510→      case 'publicAwarenessBonus':
   511→        // Increase public awareness/understanding of AI benefits
   512→        // This could map to education or trust
   513→        if (gameState.globalMetrics) {
   514→          gameState.globalMetrics.publicTrust = Math.min(
   515→            1.0,
   516→            (gameState.globalMetrics.publicTrust || 0.5) + value * 0.005
   517→          );
   518→        }
   519→        break;
   520→        
   521→      case 'healthcareBonus':
   522→        // Improve healthcare quality
   523→        if (gameState.qualityOfLifeSystems) {
   524→          gameState.qualityOfLifeSystems.healthcareQuality = Math.min(
   525→            1.0,
   526→            gameState.qualityOfLifeSystems.healthcareQuality + value * 0.01
   527→          );
   528→        }
   529→        break;
   530→        
   531→      case 'mortalityReduction':
   532→        // Reduce mortality rates (adjusting death rate)
   533→        if (gameState.humanPopulationSystem) {
   534→          gameState.humanPopulationSystem.adjustedDeathRate = Math.max(
   535→            0.001,
   536→            gameState.humanPopulationSystem.adjustedDeathRate - value * 0.01
   537→          );
   538→        }
   539→        break;
   540→
   541→      // ========== MEDICAL ==========
   542→
   543→      case 'mortalityReduction':
   544→        // Reduce mortality rate (duplicate case - should be handled above)
   545→        if (gameState.humanPopulationSystem) {
   546→          gameState.humanPopulationSystem.adjustedDeathRate = Math.max(
   547→            0.001,
   548→            gameState.humanPopulationSystem.adjustedDeathRate - value * 0.0001
   549→          );
   550→        }
   551→        break;
   552→
   553→      case 'lifeExpectancyBonus':
   554→        // Increase life expectancy (in years) - adjust death rate to reflect this
   555→        // Life expectancy increase of 1 year ~= 1% reduction in death rate
   556→        if (gameState.humanPopulationSystem) {
   557→          gameState.humanPopulationSystem.adjustedDeathRate = Math.max(
   558→            0.001,
   559→            gameState.humanPopulationSystem.adjustedDeathRate * (1 - value * 0.01)
   560→          );
   561→        }
   562→        break;
   563→        
   564→      case 'infectiousDisease':
   565→        // Reduce infectious disease burden (negative value) by reducing death rate
   566→        if (gameState.humanPopulationSystem) {
   567→          // Reduce death rate to reflect disease elimination
   568→          gameState.humanPopulationSystem.adjustedDeathRate = Math.max(
   569→            0.001,
   570→            gameState.humanPopulationSystem.adjustedDeathRate - Math.abs(value) * 0.0001
   571→          );
   572→        }
   573→        break;
   574→        
   575→      case 'pandemicResponse':
   576→        // Improve pandemic response capability
   577→        if (gameState.globalMetrics) {
   578→          const current = getDynamicProperty(gameState.globalMetrics, 'pandemicPreparedness', 0);
   579→          setDynamicProperty(gameState.globalMetrics, 'pandemicPreparedness', Math.min(1.0, current + value));
   580→        }
   581→        break;
   582→    }
   583→  }
   584→}
   585→
   586→/**
   587→ * Apply regional effects to game state
   588→ * These effects vary by region (e.g., desalination helps coasts more than inland)
   589→ */
   590→function applyRegionalEffects(
   591→  gameState: GameState,
