     1→/**
     2→ * Assertion Utilities for Exposing Bugs at Their Source
     3→ *
     4→ * Replace defensive programming (silent NaN/undefined replacement)
     5→ * with assertive programming (fail fast with context).
     6→ *
     7→ * Philosophy: If a value is unexpectedly NaN/Infinity/undefined,
     8→ * that's a BUG that needs fixing, not a value that needs replacing.
     9→ */
    10→
    11→import type { GameState } from '@/types/game';
    12→
    13→/**
    14→ * Assert a number is finite (not NaN, not Infinity, not -Infinity)
    15→ *
    16→ * @throws Error with full context if value is non-finite
    17→ */
    18→export function assertFinite(
    19→  value: number,
    20→  context: {
    21→    location: string;      // e.g. "calculateFoodSecurity"
    22→    valueName: string;     // e.g. "foodSecurity"
    23→    month?: number;        // current simulation month
    24→    additionalInfo?: Record<string, any>;  // extra debug data
    25→  }
    26→): number {
    27→  if (!isFinite(value)) {
    28→    const errorMsg = [
    29→      `❌ Non-finite value in ${context.location}`,
    30→      `   ${context.valueName} = ${value}`,
    31→      context.month !== undefined ? `   Month: ${context.month}` : '',
    32→      context.additionalInfo ? `   Context: ${JSON.stringify(context.additionalInfo, null, 2)}` : '',
    33→    ].filter(Boolean).join('\n');
    34→
    35→    throw new Error(errorMsg);
    36→  }
    37→  return value;
    38→}
    39→
    40→/**
    41→ * Assert a value is defined (not undefined, not null)
    42→ *
    43→ * @throws Error with full context if value is undefined/null
    44→ */
    45→export function assertDefined<T>(
    46→  value: T | undefined | null,
    47→  context: {
    48→    location: string;
    49→    valueName: string;
    50→    month?: number;
    51→    expectedSource?: string;  // e.g. "initialization.ts:559"
    52→  }
    53→): T {
    54→  if (value === undefined || value === null) {
    55→    const errorMsg = [
    56→      `❌ Undefined value in ${context.location}`,
    57→      `   ${context.valueName} is ${value === null ? 'null' : 'undefined'}`,
    58→      context.month !== undefined ? `   Month: ${context.month}` : '',
    59→      context.expectedSource ? `   Expected source: ${context.expectedSource}` : '',
    60→      '',
    61→      '   This indicates an initialization bug or missing state assignment.',
    62→    ].filter(Boolean).join('\n');
    63→
    64→    throw new Error(errorMsg);
    65→  }
    66→  return value;
    67→}
    68→
    69→/**
    70→ * Assert a number is in valid range [min, max]
    71→ *
    72→ * @throws Error if value is outside range or non-finite
    73→ */
    74→export function assertInRange(
    75→  value: number,
    76→  min: number,
    77→  max: number,
    78→  context: {
    79→    location: string;
    80→    valueName: string;
    81→    month?: number;
    82→  }
    83→): number {
    84→  assertFinite(value, context);
    85→
    86→  if (value < min || value > max) {
    87→    const errorMsg = [
    88→      `❌ Out-of-range value in ${context.location}`,
    89→      `   ${context.valueName} = ${value}`,
    90→      `   Valid range: [${min}, ${max}]`,
    91→      context.month !== undefined ? `   Month: ${context.month}` : '',
    92→    ].filter(Boolean).join('\n');
    93→
    94→    throw new Error(errorMsg);
    95→  }
    96→  return value;
    97→}
    98→
    99→/**
   100→ * Assert a probability is valid [0, 1]
   101→ *
   102→ * @throws Error if not a valid probability
   103→ */
   104→export function assertProbability(
   105→  value: number,
   106→  context: {
   107→    location: string;
   108→    valueName: string;
   109→    month?: number;
   110→  }
   111→): number {
   112→  return assertInRange(value, 0, 1, {
   113→    ...context,
   114→    valueName: `${context.valueName} (probability)`,
   115→  });
   116→}
   117→
   118→/**
   119→ * Assert array is non-empty
   120→ *
   121→ * @throws Error if array is empty or undefined
   122→ */
   123→export function assertNonEmpty<T>(
   124→  array: T[] | undefined,
   125→  context: {
   126→    location: string;
   127→    valueName: string;
   128→    month?: number;
   129→  }
   130→): T[] {
   131→  if (!array || array.length === 0) {
   132→    const errorMsg = [
   133→      `❌ Empty array in ${context.location}`,
   134→      `   ${context.valueName} has ${array ? '0' : 'undefined'} elements`,
   135→      context.month !== undefined ? `   Month: ${context.month}` : '',
   136→    ].filter(Boolean).join('\n');
   137→
   138→    throw new Error(errorMsg);
   139→  }
   140→  return array;
