  system.effects.trustBuilding = avgPhysical * 0.006 + avgPrograms * 0.010;
  state.society.trustInAI = Math.min(
    1.0,
    state.society.trustInAI + system.effects.trustBuilding * 0.5 // Half effect on AI trust
  );

