  // === EXTINCTION PATHWAY ===
  // Slow collapse: Reproductive failure + chronic disease = population decline
  // Timeline: 100-200 years (1200-2400 months)

  if (ne.reproductiveHealthDecline > 0.70 && ne.chronicDiseasePrevalence > 0.60) {
