  // Harvesting water from air humidity
  if (!tech.atmosphericWater?.unlocked) {
    if (avgAICapability > 3.0 && totalResearch > 200) {
      tech.atmosphericWater = {
        unlocked: true,
        deploymentLevel: 0.0,
        breakthroughYear: Math.floor(state.currentMonth / 12) + 2025
      };
